import React from "react";
import {
  BrowserRouter,
  Routes,
  Route
} from "react-router-dom";

import Login from "./pages/Login";
import Dashboard from "./pages/Dashboard";
import Threats from "./pages/Threats";
import Incidents from "./pages/Incidents";
import Packets from "./pages/Packets";
import Malware from "./pages/Malware";
import ThreatIntel from "./pages/ThreatIntel";

import ProtectedRoute from "./components/ProtectedRoute";
import Sidebar from "./components/Sidebar";

function App() {
  return (
    <BrowserRouter>
      <div style={{ display: "flex" }}>
        <Sidebar />

        <Routes>
          <Route
            path="/"
            element={<Login />}
          />

          <Route
            path="/dashboard"
            element={
              <ProtectedRoute>
                <Dashboard />
              </ProtectedRoute>
            }
          />

          <Route
            path="/threats"
            element={
              <ProtectedRoute>
                <Threats />
              </ProtectedRoute>
            }
          />

          <Route
            path="/incidents"
            element={
              <ProtectedRoute>
                <Incidents />
              </ProtectedRoute>
            }
          />

          <Route
            path="/packets"
            element={
              <ProtectedRoute>
                <Packets />
              </ProtectedRoute>
            }
          />

          <Route
            path="/malware"
            element={
              <ProtectedRoute>
                <Malware />
              </ProtectedRoute>
            }
          />

          <Route
            path="/intel"
            element={
              <ProtectedRoute>
                <ThreatIntel />
              </ProtectedRoute>
            }
          />
        </Routes>
      </div>
    </BrowserRouter>
  );
}

export default App;
